import React, { useEffect, useState } from 'react';
import confetti from 'canvas-confetti';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Videos from './components/Videos';
import Shows from './components/Shows';
import Merch from './components/Merch';
import Hecklers from './components/Hecklers';
import Contact from './components/Contact';
import Footer from './components/Footer';
import Popup from './components/Popup';

const App: React.FC = () => {
  const [konamiInput, setKonamiInput] = useState<string[]>([]);
  const KONAMI_CODE = ['ArrowUp', 'ArrowUp', 'ArrowDown', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ArrowLeft', 'ArrowRight', 'b', 'a'];

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const newInput = [...konamiInput, e.key];
      if (newInput.length > KONAMI_CODE.length) {
        newInput.shift();
      }
      setKonamiInput(newInput);

      if (JSON.stringify(newInput) === JSON.stringify(KONAMI_CODE)) {
        triggerEasterEgg();
        setKonamiInput([]);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [konamiInput]);

  const triggerEasterEgg = () => {
    const duration = 5 * 1000;
    const animationEnd = Date.now() + duration;
    const defaults = { startVelocity: 30, spread: 360, ticks: 60, zIndex: 100 };

    const randomInRange = (min: number, max: number) => Math.random() * (max - min) + min;

    const interval: any = setInterval(function() {
      const timeLeft = animationEnd - Date.now();

      if (timeLeft <= 0) {
        return clearInterval(interval);
      }

      const particleCount = 50 * (timeLeft / duration);

      confetti({ 
        ...defaults, 
        particleCount, 
        origin: { x: randomInRange(0.1, 0.3), y: Math.random() - 0.2 },
        colors: ['#f8e434', '#c62828', '#64b5f6']
      });
      confetti({ 
        ...defaults, 
        particleCount, 
        origin: { x: randomInRange(0.7, 0.9), y: Math.random() - 0.2 },
        colors: ['#f8e434', '#c62828', '#64b5f6']
      });
    }, 250);

    alert("BANANA MODE ACTIVATED!");
  };

  return (
    <div className="font-body bg-sky text-jet min-h-screen selection:bg-banana selection:text-jet">
      <Navbar />
      <Hero />
      <About />
      <Videos />
      <Shows />
      <Merch />
      <Hecklers />
      <Contact />
      <Footer />
      <Popup />
    </div>
  );
};

export default App;

